import { NextRequest, NextResponse } from "next/server";
import { GSC_DATA } from "@/app/data/gsc-data";

function fmt(n: number | null) {
  if (n === null) return "N/A";
  return n.toLocaleString("en-IN");
}

function momPct(cur: number, prev: number) {
  return ((cur - prev) / prev) * 100;
}

function getDateLabels() {
  const today = new Date();
  const endDay = today.getDate() - 2;
  const curMonth  = today.toLocaleString("en-US", { month: "short" });
  const curMonthLong = today.toLocaleString("en-US", { month: "long" });
  const curYear   = today.getFullYear();
  const prevMonthDate = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const prevMonth = prevMonthDate.toLocaleString("en-US", { month: "short" });

  return {
    endDay,
    curLabel:     `1–${endDay} ${curMonth}`,
    prevLabel:    `1–${endDay} ${prevMonth}`,
    reportPeriod: `1 ${curMonth} ${curYear} to ${endDay} ${curMonth} ${curYear}`,
    monthLabel:   `${curMonthLong} ${curYear} (1–${endDay}th)`,
    curMonthShort: curMonth,
  };
}

const PROJECTS = ["Cars24 – New Cars", "Bikes24", "TeamBHP New Cars", "TeamBHP New Bikes"] as const;
type ProjectKey = typeof PROJECTS[number];

const PROJECT_META: Record<ProjectKey, { emoji: string; shortName: string }> = {
  "Cars24 – New Cars":  { emoji: "🚗",  shortName: "Cars24 New Cars"   },
  "Bikes24":            { emoji: "🏍️", shortName: "Bikes24"           },
  "TeamBHP New Cars":   { emoji: "🏎️", shortName: "TeamBHP New Cars"  },
  "TeamBHP New Bikes":  { emoji: "🏍️", shortName: "TeamBHP New Bikes" },
};

function buildReport(contentCount: number) {
  const { curLabel, prevLabel, reportPeriod, monthLabel, curMonthShort } = getDateLabels();
  const d = GSC_DATA;

  // Totals
  const totalCur  = PROJECTS.reduce((s, k) => s + (d.curPeriod[k].clicks  ?? 0), 0);
  const totalPrev = PROJECTS.reduce((s, k) => s + (d.prevPeriod[k].clicks ?? 0), 0);
  const totalFeb  = PROJECTS.reduce((s, k) => s + (d.feb[k].clicks        ?? 0), 0);
  const totalJan  = PROJECTS.reduce((s, k) => s + (d.jan[k].clicks        ?? 0), 0);
  const totalDec  = PROJECTS.reduce((s, k) => s + (d.dec[k].clicks        ?? 0), 0);

  const combinedMomVal = momPct(totalCur, totalPrev);
  const combinedMom = `${combinedMomVal >= 0 ? "+" : ""}${combinedMomVal.toFixed(1)}%`;

  // Per-project stats
  const stats = PROJECTS.map((k) => {
    const cur      = d.curPeriod[k].clicks   ?? 0;
    const prev     = d.prevPeriod[k].clicks  ?? 0;
    const posCur   = d.curPeriod[k].position ?? 0;
    const posPrev  = d.prevPeriod[k].position ?? 0;
    const mom      = momPct(cur, prev);
    const posImprove = posPrev - posCur; // positive = improved ranking
    return { k, cur, prev, mom, posCur, posPrev, posImprove };
  });

  // Narrative — sort by MoM descending (positive performers first)
  const sorted = [...stats].sort((a, b) => b.mom - a.mom);
  const growingCount = stats.filter((s) => s.mom > 0).length;

  const narrativeLines: string[] = sorted.map(({ k, cur, prev, mom, posCur, posPrev, posImprove }) => {
    const name = PROJECT_META[k].shortName;
    const sign = mom >= 0 ? "+" : "";
    const momStr = `${sign}${mom.toFixed(1)}%`;

    if (mom >= 0) {
      const posNote = Math.abs(posImprove) < 0.1
        ? `stable rankings at ${posCur.toFixed(1)}`
        : `avg position improved from ${posPrev.toFixed(1)} → ${posCur.toFixed(1)}`;
      return `${name} up ${momStr} MoM (${fmt(prev)} → ${fmt(cur)} clicks) — ${posNote}`;
    } else {
      if (posImprove > 0.05) {
        return `${name} dipped ${momStr} MoM despite improved rankings (${posPrev.toFixed(1)} → ${posCur.toFixed(1)}) — CTR issue, likely SERP layout changes or snippet displacement reducing click share`;
      }
      return `${name} dipped ${momStr} MoM — rankings slipped from ${posPrev.toFixed(1)} → ${posCur.toFixed(1)}, review content and coverage`;
    }
  });

  narrativeLines.push(
    `${contentCount} content pieces shipped in ${curMonthShort} so far — should fuel recovery through month end`
  );

  const combinedTrend = Math.abs(combinedMomVal) < 0.5 ? "flat" : combinedMomVal > 0 ? "up" : "down";
  narrativeLines.push(
    `Overall combined ${combinedTrend} at ${fmt(totalCur)} clicks (${combinedMom} MoM) — ${growingCount} of ${PROJECTS.length} projects growing`
  );

  // At a glance — sorted by current clicks descending
  const atAGlance = [...stats]
    .sort((a, b) => b.cur - a.cur)
    .map(({ k, cur, mom, posCur, posImprove }) => {
      const momDir: "up" | "down" | "flat" = mom > 0.05 ? "up" : mom < -0.05 ? "down" : "flat";
      const momStr = `${mom >= 0 ? "↑" : "↓"}${Math.abs(mom).toFixed(1)}%`;
      const posStr = Math.abs(posImprove) < 0.05
        ? "↔0.0"
        : posImprove > 0
          ? `↑${posImprove.toFixed(1)}`
          : `↓${Math.abs(posImprove).toFixed(1)}`;
      const posDir: "up" | "down" | "flat" = posImprove > 0.05 ? "up" : posImprove < -0.05 ? "down" : "flat";

      return {
        emoji: PROJECT_META[k].emoji,
        name: PROJECT_META[k].shortName,
        clicks: fmt(cur),
        momPct: momStr,
        momDir,
        posCur: posCur.toFixed(1),
        posChange: posStr,
        posDir,
      };
    });

  return {
    curLabel,
    prevLabel,
    reportPeriod,
    monthLabel,
    narrative: narrativeLines,
    contentCount,
    combinedClicks: fmt(totalCur),
    combinedMom: `${combinedMomVal >= 0 ? "↑" : "↓"}${Math.abs(combinedMomVal).toFixed(1)}%`,
    atAGlance,
    clicks: {
      rows: PROJECTS.map((k) => ({
        name: k,
        cur:  fmt(d.curPeriod[k].clicks),
        prev: fmt(d.prevPeriod[k].clicks),
        feb:  fmt(d.feb[k].clicks),
        jan:  fmt(d.jan[k].clicks),
        dec:  fmt(d.dec[k].clicks),
      })),
      total: {
        cur:  fmt(totalCur),
        prev: fmt(totalPrev),
        feb:  fmt(totalFeb),
        jan:  fmt(totalJan),
        dec:  fmt(totalDec),
      },
    },
    position: PROJECTS.map((k) => ({
      name: k,
      cur:  d.curPeriod[k].position  ?? "N/A",
      prev: d.prevPeriod[k].position ?? "N/A",
      feb:  d.feb[k].position        ?? "N/A",
      jan:  d.jan[k].position        ?? "N/A",
    })),
    content: { mar: contentCount, feb: 104, jan: 160, dec: 89 },
  };
}

export async function POST(req: NextRequest) {
  const { message, step } = await req.json() as { message: string; step: string };
  const lower = message.toLowerCase().trim();

  if (step === "idle" && (lower.includes("send report") || lower.includes("report"))) {
    return NextResponse.json({
      reply: "Sure! How many content pieces were shipped this month?",
      nextStep: "awaiting_count",
    });
  }

  if (step === "awaiting_count") {
    const num = parseInt(message.replace(/[^0-9]/g, ""), 10);
    if (isNaN(num)) {
      return NextResponse.json({
        reply: "Please enter a valid number (e.g. 79).",
        nextStep: "awaiting_count",
      });
    }
    const report = buildReport(num);
    return NextResponse.json({
      reply: "Here's your report preview. Ready to post to Slack?",
      report,
      nextStep: "idle",
    });
  }

  return NextResponse.json({
    reply: 'Type "send report" or click the button to preview the organic traffic report.',
    nextStep: "idle",
  });
}

