"use client";

import { useState, useRef, useEffect } from "react";

type AtAGlance = {
  emoji: string;
  name: string;
  clicks: string;
  momPct: string;
  momDir: "up" | "down" | "flat";
  posCur: string;
  posChange: string;
  posDir: "up" | "down" | "flat";
};

type ClickRow = { name: string; cur: string; prev: string; feb: string; jan: string; dec: string };
type PosRow   = { name: string; cur: string | number; prev: string | number; feb: string | number; jan: string | number };

type Report = {
  curLabel:      string;
  prevLabel:     string;
  reportPeriod:  string;
  monthLabel:    string;
  narrative:     string[];
  contentCount:  number;
  combinedClicks: string;
  combinedMom:   string;
  atAGlance:     AtAGlance[];
  clicks:        { rows: ClickRow[]; total: ClickRow };
  position:      PosRow[];
  content:       { mar: number; feb: number; jan: number; dec: number };
};

type Message = { role: "user" | "assistant"; text: string; report?: Report; isWelcome?: boolean };

function MomBadge({ value, dir }: { value: string; dir: "up" | "down" | "flat" }) {
