            <p className="text-xs text-zinc-400">New Auto – Organic Traffic · #aakash-ai-experiment</p>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col gap-4">
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}>
              <div className={`max-w-full rounded-2xl px-4 py-3 text-sm leading-relaxed ${
                msg.role === "user"
                  ? "bg-zinc-900 text-white dark:bg-white dark:text-black rounded-br-sm max-w-[70%]"
                  : "bg-zinc-100 text-zinc-800 dark:bg-zinc-800 dark:text-zinc-100 rounded-bl-sm w-full"
              }`}>
                {msg.isWelcome ? (
                  <div className="flex flex-col gap-3">
                    <div>
                      <p className="font-semibold text-zinc-900 dark:text-zinc-100">New Auto – Organic Traffic</p>
                      <p className="text-zinc-500 dark:text-zinc-400 text-xs mt-0.5">
                        Generate and preview the weekly SEO report
                      </p>
                    </div>
                    <button
                      onClick={() => handleSend("send report")}
                      disabled={loading}
                      className="self-start flex items-center gap-2 rounded-xl bg-zinc-900 dark:bg-white px-4 py-2 text-sm font-medium text-white dark:text-black hover:bg-zinc-700 dark:hover:bg-zinc-200 disabled:opacity-40 transition-colors"
                    >
                      📊 Send Report
                    </button>
                  </div>
                ) : (
                  <>
                    {msg.text}
                    {msg.report && <ReportTable report={msg.report} />}
                  </>
                )}
